
/* =============== 5.2 flashcards & mnemonics =============== */
const PARTN={1:"חלק 1 · המחלה",2:"חלק 2 · מהלך ואבחון",3:"חלק 3 · טיפול",4:"חלק 4 · חיים, טיפול ומניעה",5:"חלק 5 · הקשר וחזרה"};
const FC=[
[1,'האם דמנציה ומחלת אלצהיימר הן אותו דבר?','לא. דמנציה היא תסמונת קלינית: בעיות קוגניטיביות שמפריעות למשימות יומיומיות כמו נהיגה, בישול או ניקיון. מחלת אלצהיימר היא הגורם השכיח ביותר שלה. גורמים אחרים הם, למשל, מחלה מוחית־כלית, ניוון פרונטו־טמפורלי ומחלת גופיפי לוי.'],
[1,'איזה חלק ממקרי הדמנציה נובע ממחלת אלצהיימר?','המקורות חלוקים. איגוד האלצהיימר (Alzheimer’s Association) מעריך 60% עד 80% ממקרי הדמנציה, ואילו דף העובדות של ארגון הבריאות העולמי (WHO) מציין 60% עד 70%. אצל רוב האנשים עם אלצהיימר יש במוח גם שינויים של גורם נוסף (פתולוגיה מעורבת).'],
[1,'כמה אנשים חיו עם דמנציה בעולם ב־2021, לפי WHO?','57 מיליון, יותר מ־60% מהם במדינות בעלות הכנסה נמוכה ובינונית. לפי WHO נוספים מדי שנה כמעט 10 מיליון מקרים חדשים.'],
[1,'כמה אמריקאים מבוגרים חיו עם דמנציה של אלצהיימר ב־2025?','לפי הערכה, 7.2 מיליון בני 65 ומעלה (איגוד האלצהיימר, 2025). זהו בערך 1 מכל 9 אנשים בקבוצת גיל זו, וכמעט שני שלישים מהם נשים.'],
[1,'בנתיחות שלאחר המוות של Rush Memory and Aging Project, באיזו תדירות הייתה אלצהיימר הפתולוגיה היחידה אצל אנשים עם דמנציה?','ב־30%. הממצא השכיח ביותר היה אלצהיימר יחד עם אוטמים (38%), ויותר ממחצית קיבלו כמה אבחנות. בנוסף, אצל 24.2% מהאנשים ללא דמנציה נמצאה פתולוגיה של אלצהיימר בלבד.'],
[1,'איזה אנזים מתחיל את המסלול העמילואידוגני, ואיזה מונע היווצרות של Aβ?','BACE1 (בטא־סקרטאז) חותך את APP בתחילת רצף ה־Aβ ומשאיר את המקטע C99. אלפא־סקרטאז (ADAM10) חותך בתוך רצף ה־Aβ, ולכן לא ניתן לייצר Aβ.'],
[1,'ממה עשוי גמא־סקרטאז?','מארבעה רכיבים: פרסנילין (PS1 או PS2, היחידה הקטליטית), ניקסטרין, APH-1 ו־PEN-2. הוא חותך את C99 בתוך הממברנה ומשחרר את Aβ ואת המקטע התוך־תאי AICD.'],
[1,'Aβ40 או Aβ42: איזה מהם שכיח יותר, ואיזה דביק יותר?','Aβ40 הוא רוב ה־Aβ שמיוצר. Aβ42 הוא רק כ־10%, אבל הוא הידרופובי יותר, יוצר סיבים ביתר קלות והוא הרכיב העיקרי של הרבדים. העמילואיד שבדפנות כלי הדם (CAA) עשיר ב־Aβ40.'],
[1,'באיזה סדר מצטבר Aβ?','מונומר, אחר כך אוליגומר, אחר כך פרוטופיבריל, אחר כך סיב, ולבסוף רובד. משערים שאוליגומרים מסיסים הם שמניעים את הנזק לסינפסות, ואילו רבדים גדולים עשויים לשמש מאגרים.'],
[1,'במה שונים רבדים מפוזרים מרבדים נויריטיים?','רבדים מפוזרים נצבעים חלש, ואין סביבם נויריטים פגועים וגליה משופעלת. רבדים נויריטיים הם רבדים בעלי ליבה צפופה, המוקפים בנויריטים נפוחים חיוביים לטאו, במיקרוגליה משופעלת, באסטרוציטים ריאקטיביים ובאובדן סינפסות.'],
[1,'מה תפקידו הרגיל של טאו?','טאו הוא חלבון של נוירונים, המרוכז באקסונים, שעוזר לטובולין להתארגן למיקרוטובולים ושומר על יציבותם. הוא מקודד בגן MAPT שעל כרומוזום 17, והמוח הבוגר מייצר שש איזופורמות (3R ו־4R).'],
[1,'ממה עשוי סבך נוירופיברילרי?','מטאו בהיפר־זרחון שהתארגן לסיבים סליליים זוגיים, שני סיבים המלופפים זה סביב זה, הצרורים יחד בתוך הנוירון. כשהנוירון מת, נשאר אחריו מחוץ לתא "סבך רפאים".'],
[1,'מהם שלבי Braak של התפשטות הסבכים?','שלבים I-II: הקליפה הטרנס־אנטורינלית. שלבים III-IV: האזורים הלימביים, כשקליפת המוח האנטורינלית מעורבת במלואה ו־CA1 והסוביקולום נפגעים. שלבים V-VI: האיזוקורטקס האסוציאטיבי, ולבסוף אפילו קליפת המוח התחושתית הראשונית.'],
[1,'היכן שוקע העמילואיד לראשונה לפי שלבי Thal?','בניאוקורטקס (שלב 1). משם הוא מתפשט לאלוקורטקס (2), לדיאנצפלון, לסטריאטום ולמוח הקדמי הבזאלי (3), לגזע המוח (4) ולמוח הקטן (5). הסבכים, לעומת זאת, מתחילים בקליפה הטרנס־אנטורינלית.'],
[1,'מה מתואם הכי טוב עם חומרת הבעיות הקוגניטיביות: רבדים, סבכים או סינפסות?','עומס הרבדים מתואם רק בחולשה. הסבכים בניאוקורטקס מתואמים טוב יותר, ובמחקר קלאסי מ־1991 צפיפות הסינפסות בניאוקורטקס הייתה בעלת המתאם החזק מכולם.'],
[1,'מדוע הזיכרון האפיזודי נפגע בדרך כלל ראשון?','הסבכים הראשונים ואובדן הנוירונים פוגעים בשכבה II של הקליפה האנטורינלית, השולחת את המסילה המחוררת (perforant path) אל ההיפוקמפוס, ואחר כך ב־CA1 ובסוביקולום. כך ההיפוקמפוס מתנתק מהקלטים ומהפלטים שלו.'],
[1,'מה קורה לגרעין הבזאלי של מיינרט במחלת אלצהיימר?','הנוירונים שלו, מקור הקלט הכולינרגי העיקרי לקליפת המוח, מתנוונים במידה ניכרת (יותר מ־75%). זה הבסיס לחסר האצטילכולין בקליפת המוח, שאליו מכוונים מעכבי כולינאסטראז.'],
[1,'מהו TREM2, ומה הראה הווריאנט R47H?','TREM2 הוא קולטן על פני המיקרוגליה. הווריאנט הנדיר R47H העלה את הסיכון לאלצהיימר פי 2.9 בערך אצל איסלנדים. בלי TREM2 המיקרוגליה אינה מצליחה לעטוף את הרבדים, ולכן סביבם נזק נויריטי רב יותר.'],
[1,'אילו שלושה גנים גורמים למחלת אלצהיימר בתורשה אוטוזומלית דומיננטית, ועל אילו כרומוזומים הם נמצאים?','APP על כרומוזום 21, PSEN1 על כרומוזום 14 ו־PSEN2 על כרומוזום 1. המקורות חלוקים בשאלה כמה שכיחה צורה זו: פחות מ־1% מכלל המקרים (Bateman 2011) או פחות מ־5% (הנחיית ACMG/NSGC).'],
[1,'בכמה מעלה APOE ε4 את הסיכון לאלצהיימר?','סקירה ב־Nature Reviews מעריכה פי 3 עד 4 בערך לעותק אחד ופי 9 עד 15 לשני עותקים. ε4 מעלה את הסיכון אך אינו קובע את התוצאה: אנשים רבים עם ε4/ε4 אינם מפתחים דמנציה לעולם. ε2 מגן.'],
[1,'מדוע כמעט כל המבוגרים עם תסמונת דאון מראים פתולוגיה של אלצהיימר עד גיל 40?','APP נמצא על כרומוזום 21, ולכן עותק שלישי של הכרומוזום פירושו עודף APP. אצל אישה עם טריזומיה 21 חלקית ורק שני עותקים של APP לא נמצאה מחלת אלצהיימר בגיל 78.'],
[1,'מה משך כתב העת Nature ב־2024?','את המאמר מ־2006 של Lesne ועמיתיו, שדיווח בעכברים על צבר Aβ במשקל 56 קילודלטון (Aβ*56). המשיכה מסירה את הראיות של מאמר אחד למין אוליגומר אחד במודל עכבר אחד. ראיות אחרות להשערת העמילואיד, כמו הגנטיקה של בני אדם ולוחות הזמנים של הסמנים הביולוגיים, אינן נשענות עליו.'],
[2,'במפל הסמנים הביולוגיים ההיפותטי, מה משתנה ראשון?','סמני העמילואיד: Aβ42 ב־CSF יורד והקליטה ב־PET עמילואיד עולה, בזמן שהאדם עדיין תקין קוגניטיבית. סמני הניוון העצבי (טאו ב־CSF, אטרופיה ב־MRI, ירידה בקליטה ב־FDG-PET) מגיעים באיחור, והם עוקבים אחרי חומרת התסמינים.'],
[2,'מה הראה מחקר DIAN על התזמון באלצהיימר בתורשה דומיננטית?','ביחס לגיל ההופעה הצפוי: Aβ42 ב־CSF החל לרדת כ־25 שנה לפני, PET עמילואיד, טאו ב־CSF ואטרופיה כ־15 שנה לפני, היפומטבוליזם וזיכרון אפיזודי כ־10 שנים לפני, וקוגניציה כללית כ־5 שנים לפני. הקריטריונים לדמנציה התמלאו כ־3 שנים אחרי.'],
[2,'מהו סמן ביולוגי מסוג Core 1 בקריטריונים של איגוד האלצהיימר מ־2024?','סמן שהופך לא תקין בערך באותו זמן כמו PET עמילואיד: PET עמילואיד עצמו, בדיקות CSF מאושרות, או בדיקות פלזמה מדויקות, במיוחד p-tau217. לפי קריטריונים אלה, תוצאה לא תקינה אחת של Core 1 מספיקה כדי לקבוע את האבחנה.'],
[2,'במה חולקת קבוצת העבודה הבינלאומית (IWG 2024) על הקריטריונים של איגוד האלצהיימר מ־2024?','ה־IWG דוחה הגדרה ביולוגית בלבד לשימוש קליני. לדבריה, אנשים תקינים קוגניטיבית שרק חיוביים לעמילואיד צריכים להיות מתוארים כנמצאים בסיכון לאלצהיימר, ולא כחולים בה. שתי הקבוצות ממליצות שלא לבדוק אנשים ללא פגיעה קוגניטיבית מחוץ למחקר.'],
[2,'מהם השלבים הביולוגיים A עד D בקריטריונים של 2024?','A: PET עמילואיד חיובי ללא קליטה ב־PET טאו. B: קליטת טאו באונה הרקתית המדיאלית. C: טאו בינוני בניאוקורטקס. D: טאו גבוה בניאוקורטקס.'],
[2,'מהם השלבים הקליניים 0 עד 6 בקריטריונים של 2024?','0: נשאות של גן דטרמיניסטי, סמנים ביולוגיים תקינים. 1: ללא תסמינים, סמנים ביולוגיים לא תקינים. 2: ירידה מעברית. 3: פגיעה קוגניטיבית עם השפעה תפקודית מוקדמת. 4: דמנציה קלה. 5: דמנציה בינונית. 6: דמנציה קשה.'],
[2,'מה מייצגות האותיות A, T ו־(N) במסגרת המחקר של 2018?','A: עמילואיד (Aβ42 ב־CSF או היחס Aβ42/40, או PET עמילואיד). T: טאו (טאו מזורחן ב־CSF או PET טאו). (N): ניוון עצבי (MRI, FDG-PET או טאו כללי ב־CSF), בסוגריים משום שאינו ספציפי לאלצהיימר.'],
[2,'מהם תת־השלבים של שלב 6 בסולם FAST?','6a צורך עזרה בהתלבשות, 6b עזרה ברחצה, 6c עזרה בשימוש בשירותים, 6d אי־נקיטת שתן, 6e אי־נקיטת צואה.'],
[2,'מהם תת־השלבים של שלב 7 בסולם FAST?','7a דיבור מוגבל לכמה מילים ביום, 7b מילה מובנת אחת, 7c אובדן ההליכה, 7d אובדן היכולת לשבת, 7e אובדן החיוך, 7f אובדן היכולת להחזיק את הראש.'],
[2,'אילו שישה תחומים מדורגים בסולם הדירוג הקליני של דמנציה (CDR)?','זיכרון; התמצאות; שיפוט ופתרון בעיות; ענייני קהילה; בית ותחביבים; טיפול אישי. כל תיבה מדורגת על סמך ריאיון חצי־מובנה עם האדם ועם מוסר מידע.'],
[2,'איך מתורגמים ציוני CDR Sum of Boxes לרמת חומרה?','CDR-SB נע בין 0 ל־18. ‏0.5-4.0 מתאים ל־CDR 0.5 (מפוקפק או קל מאוד), 4.5-9.0 קל, 9.5-15.5 בינוני ו־16.0-18.0 קשה.'],
[2,'איך ממופים ציוני MMSE לרמת חומרה לפי המוסכמה?','במבחן של 30 נקודות: 30 ללא פגיעה, 26-29 מפוקפק, 21-25 קל, 11-20 בינוני, 0-10 קשה. ההתאמה לשלבי CDR הייתה חלשה בהבחנה בין תקין למפוקפק.'],
[2,'מהו ערך הסף של MoCA?','הוא שנוי במחלוקת. מחקר התיקוף המקורי ודף השאלות הנפוצות של בעלי הכלי משתמשים ב־26 ומעלה כתקין, עם תוספת נקודה אחת למי שלמד 12 שנים או פחות. מטא־אנליזה מ־2018 מצאה שסף של 23 נתן את הדיוק הטוב ביותר ל־MCI, משום שסף של 26 מנפח את התוצאות החיוביות הכוזבות אצל מבוגרים ואצל אנשים עם השכלה מועטה.'],
[2,'מהי בדיקת הדם הראשונה שה־FDA אישר כעזר לאבחון אלצהיימר?','Lumipulse G pTau217/β-Amyloid 1-42 Plasma Ratio, שאושרה ב־16 במאי 2025 למבוגרים בני 55 ומעלה עם סימנים ותסמינים של ירידה קוגניטיבית, במסגרת טיפול מומחה. ה־FDA מציין שאין זו בדיקת סקר ולא בדיקה אבחנתית העומדת בפני עצמה.'],
[2,'איזה דיוק דורשת מבדיקות דם ההנחיה של איגוד האלצהיימר מ־2025?','לפחות 90% רגישות ו־75% סגוליות לצורך מיון ראשוני (טריאז׳), כשתוצאה חיובית מאומתת ב־PET או ב־CSF. לפחות 90% בשניהם כדי להחליף PET או CSF. שתיהן המלצות מותנות, לטיפול מומחה בלבד.'],
[2,'מהן ההסתמנויות הלא־טיפוסיות (שאינן אמנסטיות) העיקריות של מחלת אלצהיימר?','אטרופיה קורטיקלית אחורית (בעיות ראייה ותפיסה מרחבית), אפזיה ראשונית מתקדמת מהסוג הלוגופני (הפסקות בחיפוש מילים, חזרה לקויה על משפטים) וצורות פרונטליות. הן כשליש מהמקרים בהופעה צעירה, אבל רק כ־6% מהמקרים בהופעה מאוחרת.'],
[2,'מהם ארבעת המאפיינים הקליניים המרכזיים של דמנציה עם גופיפי לוי?','קוגניציה משתנה, הזיות ראייה חוזרות ומובנות היטב, הפרעת התנהגות בשנת REM ופרקינסוניזם (קונצנזוס 2017).'],
[2,'כמה זמן חיים אנשים אחרי אבחנה של דמנציה של אלצהיימר?','בני 65 ומעלה חיים בממוצע 4 עד 8 שנים, וחלקם חיים 20 שנה. לגיל יש משמעות: חציון ההישרדות היה 8.3 שנים באבחנה בגיל 65 ו־3.4 שנים בגיל 90. דלקת ריאות היא סיבת המוות המיידית המזוהה השכיחה ביותר.'],
[2,'באיזו תדירות מתקדמת ירידה קוגניטיבית קלה לדמנציה?','במטא־אנליזה של 41 קוהורטות: כ־9.6% בשנה במרפאות מומחים ו־4.9% בשנה במחקרים בקהילה. רוב האנשים עם MCI לא התקדמו גם אחרי 10 שנים.'],
[3,'איך פועלים מעכבי כולינאסטראז?','הם חוסמים את פירוק האצטילכולין במרווח הסינפטי, כך שיותר אצטילכולין מגיע לקולטנים. עלוני התרופות מציינים שאין ראיות לכך שהם משנים את מהלך המחלה הבסיסית.'],
[3,'במה שונים דונפזיל, ריבסטיגמין וגלנטמין?','דונפזיל (Aricept) מעכב באופן סלקטיבי את AChE, וזמן מחצית החיים שלו כ־70 שעות. ריבסטיגמין (Exelon) הוא מעכב פסאודו־בלתי הפיך של AChE וגם של BuChE. גלנטמין (Razadyne) הוא מעכב תחרותי והפיך של AChE, עם זמן מחצית חיים של כ־7 שעות.'],
[3,'אילו מעכבי כולינאסטראז מאושרים בארה״ב לדמנציה של אלצהיימר בשלב קשה?','דונפזיל (השלב הקשה נוסף להתוויה ב־13 באוקטובר 2006) ומדבקת הריבסטיגמין. ריבסטיגמין בבליעה וגלנטמין בשחרור מושהה (ER) מאושרים למחלה קלה עד בינונית.'],
[3,'מה גודל התועלת של דונפזיל?','סקירת Cochrane מ־2018, במינון 10 mg ביום ל־26 שבועות: ADAS-Cog טוב יותר ב־2.67 נקודות בסולם של 0-70, ו־MMSE טוב יותר בכ־1 נקודה, בהשוואה לפלצבו. הסקירות מתארות את התועלת כקטנה.'],
[3,'מהן תופעות הלוואי השכיחות ביותר של מעכבי כולינאסטראז?','במערכת העיכול: בחילה, הקאות, שלשול ואובדן תיאבון, בעיקר בזמן העלאת המינון. העלונים מזהירים גם מדופק איטי, מחסם הולכה בלב ומעילפון. ריבסטיגמין בבליעה גרם לבחילה אצל 47% לעומת 12% בפלצבו.'],
[3,'איזו מין תרופה היא ממנטין?','ממנטין (Namenda) הוא אנטגוניסט לא־תחרותי (חוסם תעלה פתוחה) של קולטן NMDA, בעל זיקה נמוכה עד בינונית, המאושר לדמנציה של אלצהיימר בשלב בינוני עד קשה. סקירת Cochrane (2019) לא מצאה תועלת במחלה קלה (MMSE 20-23).'],
[3,'למה נקשר לקנמאב, ומה הראה CLARITY AD?','לקנמאב (Leqembi) נקשר בזיקה גבוהה לפרוטופיברילים מסיסים של Aβ. לאורך 18 חודשים ציון ה־CDR-SB החמיר ב־1.21 נקודות עם לקנמאב לעומת 1.66 עם פלצבו, הפרש של 0.45 נקודות (האטה של 27%).'],
[3,'למה נקשר דונאנמאב, ומה הראה TRAILBLAZER-ALZ 2?','דונאנמאב (Kisunla) נקשר ל־Aβ עם פירוגלוטמט בקצה ה־N (N3pG), שנמצא רק ברובד ששקע. בשבוע 76 ההפרש ב־CDR-SB היה 0.70 נקודות באוכלוסייה המשולבת (האטה של 29%). המינון הוחלף לפלצבו לאחר שהעמילואיד פונה.'],
[3,'מה ההבדל בין ARIA-E ל־ARIA-H?','ARIA-E היא בצקת וזוגנית או תפליט בחריצי המוח, הנראים ב־MRI ברצף FLAIR, ובדרך כלל היא חולפת. ARIA-H היא מיקרו־דימומים או סידרוזיס שטחית, הנראים ב־MRI ברצף T2* או ברצף רגיש למגנטיות (susceptibility-weighted), והיא נשארת.'],
[3,'כמה שכיחה הייתה ARIA-E בניסויי הנוגדנים המרכזיים?','לקנמאב 12.6% לעומת 1.7% בפלצבו (CLARITY AD). דונאנמאב 24.0% לעומת 2.1% (TRAILBLAZER-ALZ 2). הסיכון היה הגבוה ביותר אצל הומוזיגוטים ל־APOE ε4.'],
[3,'מדוע עלוני הנוגדנים מזכירים תרופות טרומבוליטיות?','ARIA-E עלולה לחקות שבץ, ודימומים מוחיים קטלניים אירעו לאחר טרומבוליזה אצל מטופלים שקיבלו נוגדנים. העלונים ממליצים לשקול ARIA-E לפני מתן תרופה טרומבוליטית.'],
 [3,'האם התועלת של הנוגדנים נגד עמילואיד משמעותית קלינית?','זו שאלה שנויה במחלוקת. מטא־אנליזה מ־2024 מצאה שאף אחד מהנוגדנים לא עבר את ההפרש המינימלי החשוב קלינית. חוקרים אחרים טוענים שאי־אפשר להשוות ספים ברמת הפרט (כ־1 עד 2 נקודות CDR-SB) להפרשים בין קבוצות בניסוי. NICE העריך שהתועלת צנועה והעלות גבוהה מדי; ה־FDA אישר את שתי התרופות.'],
[3,'מה אומרת האזהרה המודגשת (boxed warning) על תרופות אנטי־פסיכוטיות בדמנציה?','ניתוחים מאוחדים של 17 ניסויים מבוקרי פלצבו הראו סיכון מוות גבוה פי 1.6 עד 1.7, כ־4.5% לעומת 2.6% במשך 10 שבועות. רוב מקרי המוות היו קרדיווסקולריים או זיהומיים.'],
[3,'לאיזו התוויה אושר ברקספיפרזול?','לאי־שקט הקשור לדמנציה עקב מחלת אלצהיימר (FDA, ‏11 במאי 2023), התרופה הראשונה שאושרה לכך. האזהרה המודגשת על תמותה, המשותפת לכל הקבוצה, נשארת בעלון, והעלון מציין שהתרופה אינה מיועדת לשימוש לפי הצורך.'],
[3,'מה מייצגות האותיות DICE?','Describe, Investigate, Create, Evaluate (תיאור, בירור, יצירה, הערכה): גישה המתמקדת במטפל לתסמינים התנהגותיים, שמחפשת גורמים (צרכים שלא נענו, בעיות רפואיות, גורמים הקשורים למטפל ולסביבה) לפני ששוקלים תרופות.'],
[3,'אילו תסמינים נוירופסיכיאטריים שכיחים ביותר במחלת אלצהיימר?','במטא־אנליזה שהשתמשה ב־Neuropsychiatric Inventory: אדישות 49%, דיכאון 42%, תוקפנות 40%, חרדה 39% והפרעת שינה 39%. במחקר אוכלוסייה, ל־75% מהאנשים עם דמנציה היה תסמין כלשהו בחודש האחרון.'],
[3,'מה מצא ניסוי CitAD של ציטלופרם לאי־שקט?','האי־שקט השתפר, אבל ה־MMSE ירד בכ־1 נקודה ומקטע ה־QTc התארך ב־18.1 ms. המינון שנבדק, 30 mg, גבוה מהמקסימום שבעלון, 20 mg ביום, לאנשים מעל גיל 60.'],
[4,'כמה גורמי סיכון ברי־שינוי מנתה ועדת Lancet ב־2024, ואיזה חלק מהדמנציה הם מסבירים?','14 גורמים, יחד כ־45% מהדמנציה בעולם. זהו גבול עליון שחושב במודל, בהנחה שהגורמים גורמים לדמנציה ושאפשר להסיר אותם לחלוטין. זה לא מה שהושג בניסוי כלשהו.'],
[4,'אילו גורמי סיכון נוספו ב־2024, ואילו תורמים הכי הרבה?','ירידה בראייה שאינה מטופלת וכולסטרול LDL גבוה היו חדשים. ליקוי שמיעה וכולסטרול LDL גבוה הם התורמים הבודדים הגדולים ביותר, כ־7% כל אחד.'],
[4,'מה מצא ניסוי אורח החיים הרב־תחומי FINGER?','תועלת קטנה: ציון המבחנים הנוירופסיכולוגיים השתפר ב־0.022 בשנה יותר עם תזונה, פעילות גופנית, אימון קוגניטיבי וניטור וסקולרי מאשר עם ייעוץ כללי. ניסויים רב־תחומיים אחרים (preDIVA ו־MAPT) לא הראו השפעה.'],
[4,'מה מצא SPRINT MIND על איזון לחץ דם אינטנסיבי?','יעד של פחות מ־120 mm Hg לא הפחית באופן מובהק דמנציה סבירה (HR 0.83, רווח סמך 95% 0.67-1.04), אבל הפחית ירידה קוגניטיבית קלה (HR 0.81). הניסוי נעצר מוקדם, ואולי לא הייתה לו עוצמה סטטיסטית מספקת.'],
[4,'האם מכשירי שמיעה האטו את הירידה הקוגניטיבית בניסוי ACHIEVE?','לא באופן כללי: התוצאה העיקרית הייתה שלילית. בתת־קבוצה בסיכון גבוה יותר מקוהורטת ARIC, הירידה הואטה ב־0.19 סטיית תקן במשך 3 שנים. תוצאה בתת־קבוצה תומכת ברעיון אך אינה מוכיחה אותו.'],
[4,'מה מצא הניסוי הטבעי של החיסון נגד שלבקת חוגרת בוויילס?','הזכאות נקבעה לפי תאריך הלידה. החיסון הפחית אבחנות חדשות של דמנציה במשך 7 שנים ב־3.5 נקודות אחוז, הפחתה יחסית של 20%. תוצאות דומות התקבלו באוסטרליה ובקנדה, אבל עדיין לא נבדק הדבר בניסוי אקראי.'],
[4,'כמה טיפול ללא תשלום נותנים בארה״ב המטפלים באנשים עם דמנציה?','ב־2024 נתנו 11.9 מיליון בני משפחה ומטפלים אחרים ללא שכר כ־19.2 מיליארד שעות, בשווי של 413.5 מיליארד דולר, כמעט 31 שעות למטפל בשבוע.'],
[4,'כמה שכיח דיכאון בקרב מטפלים באנשים עם דמנציה?','איגוד האלצהיימר מדווח על 30% עד 40%. מטא־אנליזה של מטפלים באנשים עם אלצהיימר מצאה 34.0%, יותר אצל מטפלות ואצל בני זוג מטפלים.'],
[4,'איזו תוכנית למטפלים דחתה את המעבר למוסד סיעודי?','תוכנית ההתערבות של NYU למטפלים (ייעוץ, קבוצות תמיכה ועזרה טלפונית זמינה לבני זוג) הפחיתה את שיעור המעבר למוסד ב־28.3%, וחציון המעבר שחזה המודל נדחה ב־557 ימים.'],
[4,'מה אומרת האגודה האמריקאית לגריאטריה על צינורות הזנה בדמנציה מתקדמת?','שהם אינם מומלצים (נייר עמדה מ־2014). האכלה ידנית קפדנית נחשבת טובה כמו הזנה בצינור מבחינת תמותה, דלקת ריאות משאיפה, תפקוד ונוחות.'],
[4,'מה הראה מחקר CASCADE על דמנציה מתקדמת במוסדות סיעודיים?','במשך 18 חודשים מתו 54.8%. בעיות אכילה היו אצל 85.8%, אירועי חום אצל 52.6% ודלקת ריאות אצל 41.1%. כשמקבלי ההחלטות מטעם הדייר הבינו את הפרוגנוזה, הסיכוי להתערבויות מכבידות היה נמוך בהרבה.'],
[4,'מהם ארבעת הפריטים של 4AT?','ערנות (Alertness: 0 או 4), AMT4 (0-2), קשב באמצעות מניית החודשים לאחור (0-2) ושינוי חריף או מהלך משתנה (0 או 4). סך של 4 ומעלה מרמז על דליריום; 1-3 מרמז על פגיעה קוגניטיבית.'],
[4,'מהם חמשת הפריטים של PAINAD?','נשימה שאינה תלויה בהשמעת קולות, השמעת קולות שליליים, הבעת פנים, שפת גוף ויכולת להירגע, כל אחד מקבל 0-2, וסך הכול 0-10.'],
[4,'מה אומר עלון מדבקת Exelon על הדבקת מדבקת הריבסטיגמין?','מדבקה אחת בכל פעם, שמוחלפת כל 24 שעות לאחר הסרת הישנה, רצוי על הגב העליון או התחתון (אחרת על הזרוע העליונה או על החזה). לפי העלון, אין להשתמש שוב באותו מקום בתוך 14 ימים ואין לחתוך את המדבקה. רוב הטעויות החמורות היו מדבקה ישנה שלא הוסרה או כמה מדבקות בבת אחת.'],
[4,'איזה תהליך מתארת הנחיית NICE SC1 למתן סמוי של תרופות בבתי אבות?','לפי ההנחיה, אין להסתיר תרופות מדייר שיש לו כשירות לקבל החלטות. אחרת: הערכת כשירות, ישיבה על טובתו של הדייר (צוות, רושם התרופה, רוקח, בן משפחה או מייצג), תיעוד הנימוקים, תוכנית מתן ובקרה סדירה.'],
[4,'מהו תרשים ABC?','תיעוד של הקדם (Antecedent: מה קרה לפני), ההתנהגות (Behaviour) והתוצאה (Consequence: מה קרה אחרי). תיעוד ABC הוא הבסיס לניתוח תפקודי של התנהגות.'],
[4,'מה קרה בניסויי המניעה העיקריים באנשים ללא תסמינים?','סולנזומאב (A4) וקרנזומאב (API Colombia), נוגדנים שאינם מפנים רובד היטב, לא הראו האטה. ניסויים בנוגדנים המפנים רובד לפני הופעת תסמינים (AHEAD 3-45 ו־TRAILBLAZER-ALZ 3) עדיין נמשכים.'],
[5,'מי הייתה אוגוסטה ד׳?','המטופלת של אלואיס אלצהיימר, שאושפזה בבית החולים הפסיכיאטרי בפרנקפורט בנובמבר 1901 (בדרך כלל מצוין 25 בנובמבר). היא נשארה שם עד מותה ב־8 באפריל 1906. התיק הרפואי שלה התגלה מחדש בפרנקפורט בדצמבר 1995.'],
[5,'מתי והיכן תיאר אלצהיימר את המחלה לראשונה?','ב־3 בנובמבר 1906, בכנס ה־37 של הפסיכיאטרים של דרום־מערב גרמניה בטובינגן. הוא תיאר רבדים וסבכים נוירופיברילריים, וההרצאה עוררה עניין מועט. הוא פרסם את המקרה ב־1907.'],
[5,'מי נתן למחלת אלצהיימר את שמה?','אמיל קרפלין, במהדורה ה־8 של ספר הלימוד שלו Psychiatrie (1910). ההפרדה בין מחלת אלצהיימר הקדם־סנילית לבין דמנציה סנילית בוטלה בכנס בבת׳סדה ב־1978.'],
[5,'מה הראו Blessed, Tomlinson ו־Roth ב־1968?','בעזרת שיטות כמותיות בניוקאסל הם הראו שמספר הרבדים מתואם עם חומרת הדמנציה, ושרבדים וסבכים מופיעים גם אצל מבוגרים ללא דמנציה.'],
[5,'מאין באה ההשערה הכולינרגית?','Davies ו־Maloney (1976) דיווחו על אובדן סלקטיבי של נוירונים כולינרגיים מרכזיים במחלת אלצהיימר. Bartus ועמיתיו ניסחו ב־1982 את ההשערה הכולינרגית של הפרעות זיכרון בגיל המבוגר.'],
[5,'על מה דיווחו Glenner ו־Wong ב־1984?','הם טיהרו וריצפו ממוחות של אנשים עם אלצהיימר חלבון עמילואיד חדש מכלי הדם של המוח, שנקרא לימים עמילואיד בטא.'],
[5,'מה הראו Grundke-Iqbal ועמיתיה ב־1986?','שטאו בזרחון חריג הוא רכיב של הסיבים הסליליים הזוגיים שבסבכים.'],
[5,'מה קרה ב־1987 וב־1991 בגנטיקה של העמילואיד?','ב־1987 שיבטו Kang ועמיתיו את מבשר העמילואיד ומיקמו את הגן שלו על כרומוזום 21. ב־1991 מצאו Goate ועמיתיו את מוטציית ה־missense הראשונה ב־APP שעוברת בתורשה יחד עם אלצהיימר משפחתי.'],
[5,'מי הציע את השערת מפל העמילואיד, ומתי?','Hardy ו־Higgins, ב־Science ב־1992, בין כמה מאמרים מ־1991-1992. היא הפכה למודל השולט של התפתחות המחלה.'],
[5,'מה מצאו מחקרי ה־APOE של 1993?','Strittmatter ועמיתיו מצאו שכיחות של אלל ε4 של 0.50 באלצהיימר משפחתי בהופעה מאוחרת, לעומת 0.16 בקבוצת הביקורת. Corder ועמיתיו הראו השפעת מינון גנטי: ככל שהיו יותר עותקי ε4, הסיכון עלה מ־20% ל־90% וגיל ההופעה הממוצע ירד מ־84 ל־68.'],
[5,'מתי אישר ה־FDA את התרופות התסמיניות הראשונות לאלצהיימר?','טקרין (Cognex) ב־9 בספטמבר 1993, הראשונה. דונפזיל (Aricept) ב־25 בנובמבר 1996. ממנטין (Namenda) ב־16 באוקטובר 2003.'],
[5,'מה קרה לאדוקנומאב?','אדוקנומאב (Aduhelm) קיבל אישור מואץ של ה־FDA ב־7 ביוני 2021, על סמך הפחתת עמילואיד, לאחר שוועדה מייעצת הצביעה בנובמבר 2020 שהראיות אינן מספיקות. ב־31 בינואר 2024 הודיעה Biogen שהיא מפסיקה את פיתוח התרופה ואת מכירתה.'],
[5,'מתי אושרו לקנמאב ודונאנמאב בארה״ב?','לקנמאב קיבל אישור מואץ ב־6 בינואר 2023 ואישור רגיל ב־6 ביולי 2023, הנוגדן הראשון נגד עמילואיד שעבר מאישור מואץ לאישור רגיל. דונאנמאב אושר ב־2 ביולי 2024.']
];
const MN=[
 ['מפל הסמנים הביולוגיים','<b>קודם עמילואיד, בסוף תסמינים.</b> סמני העמילואיד (ירידה ב־Aβ42 ב־CSF, עלייה ב־PET עמילואיד) הופכים לא תקינים בזמן שהחשיבה עדיין תקינה. PET טאו וסמני הניוון העצבי (אטרופיה, FDG-PET) מגיעים אחריהם, קרוב יותר לתסמינים. במחלה בתורשה דומיננטית סופרים לאחור את השנים שלפני גיל ההופעה הצפוי: <b>25</b> ירידה ב־Aβ42 ב־CSF, <b>15</b> PET עמילואיד, טאו ב־CSF ואטרופיה, <b>10</b> היפומטבוליזם וזיכרון אפיזודי, <b>5</b> קוגניציה כללית, ואז דמנציה כ־3 שנים אחרי. חוקרי DIAN מזהירים שייתכן שתזמונים אלה אינם חלים על המחלה הספורדית.'],
['שלבי Braak‏ I עד VI: ‏T, L, I','<b>שני שלבים לכל אזור, בתנועה החוצה.</b> I-II: הקליפה הטרנס־אנטורינלית (<b>T</b>ransentorhinal). III-IV: האזורים הלימביים (<b>L</b>imbic: קליפת המוח האנטורינלית, CA1, הסוביקולום). V-VI: האיזוקורטקס (<b>I</b>socortical: קליפת המוח האסוציאטיבית, ואחר כך אפילו האזורים הראשוניים). זהו עזר זיכרון; הוא מתאר סבכים, לא רבדים.'],
['שלבי Thal‏ 1 עד 5: ‏N, A, D, B, C','<b>העמילואיד מתחיל בחוץ ושוקע פנימה ומטה.</b> שלב 1: הניאוקורטקס (<b>N</b>eocortex). שלב 2: האלוקורטקס (<b>A</b>llocortex: היפוקמפוס, הקליפה האנטורינלית). שלב 3: החומר האפור העמוק (<b>D</b>eep grey matter: דיאנצפלון, סטריאטום, המוח הקדמי הבזאלי). שלב 4: גזע המוח (<b>B</b>rainstem). שלב 5: המוח הקטן (<b>C</b>erebellum). לעומת זאת, הטאו מתחיל עמוק, בקליפה הטרנס־אנטורינלית. זהו עזר זיכרון, לא כלי לקביעת שלב.'],
['גנים דומיננטיים: 21, 14, 1','<b>סופרים לאחור: APP 21, PSEN1 14, PSEN2 1.</b> APP יושב על כרומוזום 21, אותו כרומוזום שמופיע בשלושה עותקים בתסמונת דאון. מוטציות ב־PSEN1 נותנות את גילי ההופעה הצעירים ביותר (בדרך כלל 30 עד 50), במשפחות עם מוטציה ב־APP המחלה מתחילה בדרך כלל בשנות ה־50 לחיים, ול־PSEN2 טווח רחב, עם הופעה מאוחרת יותר אצל חלק מהנשאים.'],
['APOE: ‏2 מגן, 3 הוא הייחוס, 4 מעלה את הסיכון','<b>ε2</b> מוריד את הסיכון, <b>ε3</b> הוא הגנוטיפ להשוואה, <b>ε4</b> מעלה אותו: פי 3 עד 4 בערך לעותק אחד ופי 9 עד 15 לשני עותקים. סיכון אינו גורל: הומוזיגוטים רבים ל־ε4 אינם מפתחים דמנציה לעולם, ורוב אללי ה־APOE אצל אנשים עם אלצהיימר אינם ε4. ε4 מעלה גם את הסיכון ל־ARIA בטיפול בנוגדנים.'],
['ARIA-E לעומת ARIA-H','<b>E כמו Edema (בצקת), H כמו Haemosiderin (המוסידרין).</b> ARIA-E: בצקת וזוגנית או תפליט בחריצי המוח, נראית ברצף FLAIR, ובדרך כלל חולפת. ARIA-H: מיקרו־דימומים או סידרוזיס שטחית, נראים ברצף T2* או SWI, ונשארים. שתיהן שכיחות יותר אצל הומוזיגוטים ל־APOE ε4, ו־ARIA-E מופיעה בעיקר בחודשים הראשונים לטיפול.'],
['חמשת הפריטים של PAINAD','<b>Breathing, Noise, Face, Body, Comfort.</b> נשימה (Breathing) שאינה תלויה בהשמעת קולות, השמעת קולות שליליים (Noise), הבעת פנים (Face), שפת גוף (Body) ויכולת להירגע (Comfort): חמישה פריטים, כל אחד מקבל 0-2, וסך הכול 0-10. זהו עזר זיכרון, לא כלי קליני. טווחי החומרה המופיעים בהעתקים רבים לא תוקפו עבור הסולם הזה.'],
['4AT: ארבעה A','<b>Alertness, AMT4, Attention, Acute change.</b> ערנות (Alertness), מבחן AMT4, קשב (Attention) ושינוי חריף (Acute change). הניקוד: ערנות 0 או 4, AMT4 ‏0-2, קשב (מניית החודשים לאחור) 0-2, שינוי חריף או מהלך משתנה 0 או 4. סך של 4 ומעלה מרמז על דליריום. זהירות: בדמנציה קשה, פריטים 2 ו־3 לבדם יכולים להגיע ל־4 בלי דליריום.'],
['CAM: 1 + 2, ועוד 3 או 4','דליריום לפי Confusion Assessment Method ‏(CAM) דורש <b>1</b> הופעה חריפה עם מהלך משתנה <b>וגם 2</b> חוסר קשב, ובנוסף <b>או 3</b> חשיבה לא מאורגנת <b>או 4</b> שינוי ברמת ההכרה.'],
['DICE להתנהגות','תיאור ההתנהגות (<b>D</b>escribe). בירור הגורמים (<b>I</b>nvestigate: צרכים שלא נענו, בעיות רפואיות, גורמים הקשורים למטפל ולסביבה). יצירת תוכנית (<b>C</b>reate). הערכה אם היא הצליחה (<b>E</b>valuate). הראיות לגבי DICE עצמה עדיין מוגבלות.'],
['גורמי הסיכון לפי Lancet 2024: 1, 10, 3','<b>בתחילת החיים, 1:</b> השכלה נמוכה. <b>באמצע החיים, 10:</b> ירידה בשמיעה, כולסטרול LDL גבוה, דיכאון, פגיעת ראש, חוסר פעילות גופנית, סוכרת, עישון, יתר לחץ דם, השמנה, צריכת אלכוהול מופרזת. <b>בגיל המבוגר, 3:</b> בידוד חברתי, זיהום אוויר, ירידה בראייה שאינה מטופלת. יחד כ־45%, גבול עליון שחושב במודל בהנחה שהגורמים סיבתיים.'],
['מדבקת ריבסטיגמין: הישנה יורדת, אחת עולה, קודם הגב','כפי שמתאר העלון: מסירים את המדבקה של אתמול, מדביקים מדבקה <b>אחת</b> כל <b>24</b> שעות, רצוי על <b>הגב</b> העליון או התחתון (אחרת על הזרוע העליונה או על החזה), לא משתמשים שוב באותו מקום במשך <b>14</b> ימים ולעולם לא חותכים את המדבקה. רוב הטעויות החמורות היו מדבקה ישנה שלא הוסרה או כמה מדבקות בבת אחת.']
];
inits.review=()=>{
  let filt='all',deck=[],i=0;
  const F=[['all','כל הכרטיסיות'],...Object.keys(PARTN).map(k=>[k,'חלק '+k])];
  $('#fcFilter').innerHTML=F.map(([k,l])=>`<button class="btn" data-ff="${k}" aria-pressed="${k==='all'}">${l}</button>`).join('');
  const fc=$('#fc');
  function build(shuf){deck=FC.filter(c=>filt==='all'||String(c[0])===filt);if(shuf){const r=rng(Date.now()%1e6);for(let k=deck.length-1;k>0;k--){const j=Math.floor(r()*(k+1));[deck[k],deck[j]]=[deck[j],deck[k]]}}i=0;render()}
  function render(){const c=deck[i];fc.classList.remove('flip');
    $('#fcTagF').textContent=PARTN[c[0]]+' · שאלה';$('#fcTagB').textContent=PARTN[c[0]]+' · תשובה';
    $('#fcFront').textContent=c[1];$('#fcBack').textContent=c[2];$('#fcCount').textContent=`${i+1} מתוך ${deck.length}`;$('#fcBar').style.width=((i+1)/deck.length*100)+'%'}
  const flip=()=>fc.classList.toggle('flip');
  fc.addEventListener('click',flip);$('#fcFlip').onclick=flip;
  const next=()=>{i=(i+1)%deck.length;render()},prev=()=>{i=(i-1+deck.length)%deck.length;render()};
  $('#fcNext').onclick=next;$('#fcPrev').onclick=prev;$('#fcShuf').onclick=()=>build(true);
  $('#fcFilter').addEventListener('click',e=>{const b=e.target.closest('[data-ff]');if(!b)return;filt=b.dataset.ff;$$('[data-ff]').forEach(x=>x.setAttribute('aria-pressed',x===b));build(false)});
  document.addEventListener('keydown',e=>{if(cur!=='review')return;if(e.target.closest('input')||(e.target.closest('button')&&e.target!==fc))return;
    if(e.key===' '||e.key==='Enter'){e.preventDefault();flip()}else if(e.key==='ArrowRight')next();else if(e.key==='ArrowLeft')prev()});
  build(false);
  $('#mnList').innerHTML=MN.map(m=>`<div class="card"><b class="big">${m[0]}</b><p>${m[1]}</p></div>`).join('');
};

